import fs from "node:fs/promises";
import path from "node:path";

// Register only files generated by our own frame/audio endpoints. Never scan and
// delete arbitrary project directories, and never evict a registered media source.
export function createDerivativeCache({
  store,
  data,
  budgetBytes = 384 * 1024 ** 2,
  now = Date.now,
}) {
  const roots = [path.join(data, "frames"), path.join(data, "audio-cache")];
  const held = new Map();
  let cleanup = Promise.resolve();
  store.db.exec(
    "CREATE TABLE IF NOT EXISTS derivative_cache(path TEXT PRIMARY KEY, bytes INTEGER, used INTEGER)",
  );
  const owned = (file) =>
    roots.some((root) => path.dirname(file) === root) &&
    !file.includes(".partial.");
  function originals() {
    const protectedSet = new Set();
    for (const r of store.db.prepare("SELECT body FROM media").all()) {
      const m = JSON.parse(r.body);
      for (const f of [m.path, m.original, m.poster])
        if (f) protectedSet.add(path.resolve(f));
    }
    return protectedSet;
  }
  function prune() {
    cleanup = cleanup
      .catch(() => {})
      .then(async () => {
        const rows = store.db
          .prepare("SELECT * FROM derivative_cache ORDER BY used")
          .all();
        let bytes = rows.reduce((n, r) => n + r.bytes, 0);
        if (bytes <= budgetBytes) return;
        const sources = originals();
        for (const row of rows) {
          if (bytes <= budgetBytes) break;
          if (
            !owned(row.path) ||
            sources.has(row.path) ||
            held.has(row.path) ||
            now() - row.used < 30000
          )
            continue;
          await fs.rm(row.path, { force: true });
          store.db
            .prepare("DELETE FROM derivative_cache WHERE path=?")
            .run(row.path);
          bytes -= row.bytes;
        }
      });
    return cleanup;
  }
  async function remember(file) {
    if (!owned(file)) return;
    const stat = await fs.stat(file);
    store.db
      .prepare("INSERT OR REPLACE INTO derivative_cache VALUES(?,?,?)")
      .run(file, stat.size, now());
  }
  async function send(file, res) {
    const managed = owned(file);
    if (managed) {
      held.set(file, (held.get(file) || 0) + 1);
      let released = false;
      const release = () => {
        if (released) return;
        released = true;
        const count = held.get(file) - 1;
        if (count) held.set(file, count);
        else held.delete(file);
      };
      res.once("finish", release);
      res.once("close", release);
      try {
        const stat = await fs.stat(file);
        store.db
          .prepare("INSERT OR REPLACE INTO derivative_cache VALUES(?,?,?)")
          .run(file, stat.size, now());
      } catch (error) {
        release();
        throw error;
      }
    }
    res.sendFile(file);
    prune().catch(() => {});
  }
  const timer = setInterval(() => prune().catch(() => {}), 60000);
  timer.unref();
  return { send, remember, prune, stop: () => clearInterval(timer) };
}
